// ⓪ ENTRADA · la revisión del manual · CC#2 · 2026-10-10. Valida la llave de despacho (la de siempre, nunca escrita en el JSON) y el cuerpo: `client_id` uuid y `dry_run` BOOLEANO OBLIGATORIO.
// 🔴 Sin llave, sin cliente válido o sin `dry_run` booleano el flujo SE DETIENE aquí: no se lee ni se escribe nada.
const h = $input.first().json
const esperada = String($env.SALA_DISPATCH_KEY || '')
const recibida = String((h.headers || {})['x-sala-dispatch-key'] || '')
if (!esperada || recibida !== esperada) throw new Error('MANUAL_SIN_LLAVE · falta o no coincide x-sala-dispatch-key (o SALA_DISPATCH_KEY no está configurada) · se DETIENE')
const b = h.body || {}
if (typeof b.client_id !== 'string' || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(b.client_id)) throw new Error('MANUAL_CLIENTE_INVALIDO · `client_id` debe ser un uuid · se DETIENE')
if (typeof b.dry_run !== 'boolean') throw new Error('MANUAL_DRY_RUN_OBLIGATORIO · `dry_run` es obligatorio y debe ser true o false · se DETIENE')
// opcionales (agnóstico): el tipo de negocio decide los obligatorios del manual; «buscado_en» dice dónde se buscó lo que falta
const tipo = typeof b.tipo_de_negocio === 'string' && b.tipo_de_negocio.trim() ? b.tipo_de_negocio.trim().slice(0, 80) : null
const buscado = Array.isArray(b.buscado_en) ? b.buscado_en.filter((x) => typeof x === 'string').slice(0, 10) : null
return [{ json: { client_id: b.client_id, dry_run: b.dry_run, tipo_de_negocio: tipo, buscado_en: buscado, llave: recibida, workflow_id: String($workflow.id), workflow_execution_id: String($execution.id), costo_usd: 0 } }]

// ① GUARDA tras la preparación (S0/S1/S3, todo código). Decide si SIGUE a los pasos de modelo o termina aquí, y por qué.
//  · la preparación falló            → termina y lo DICE (nada se lee como «sin hallazgos»)
//  · sin hallazgos y eslogan ya está → no se hace nada
//  · dry_run                         → termina: NINGÚN paso de modelo corre en modo seco
const e = $('⓪ Entrada · llave').first().json
const r = $input.first().json || {}
const p = r.body ? r.body : r
if (!p || p.error || !p.informe) return [{ json: { ...e, ruta: 'fin', motivo: 'La preparación falló: ' + String((p && (p.error || p.detalle)) || 'sin respuesta') + ' ' + String((p && p.detalle) || '') } }]
if (p.sin_hallazgos === true) return [{ json: { ...e, prep: p, ruta: 'fin', motivo: 'Sin hallazgos de hecho y el eslogan ya está: no se hace nada.' } }]
if (e.dry_run === true) return [{ json: { ...e, prep: p, ruta: 'fin', motivo: 'dry_run: se preparó (materia, frases propias, hechos y evidencia del juez) y se detuvo antes de cualquier modelo.' } }]
return [{ json: { ...e, prep: p, ruta: 'seguir', motivo: '' } }]

// ② EL AUTOR CORRIGE UNA VEZ SOLO LOS HALLAZGOS DE HECHO (S4). Arma el pedido del escritor del manual (`brand-strategist`, el mismo de las lentes).
// El autor recibe el manual vigente, la MATERIA CRUDA ordenada y la lista de hallazgos. Lo creativo no se toca; el eslogan lo escribe el código, no el autor.
const e = $input.first().json
const p = e.prep
const hallazgos = (p.informe.hechos || []).filter((h) => ['sin_cita', 'solo_sintesis', 'con_duda'].includes(h.estado))
const lista = hallazgos.map((h) => '- [' + h.campo + '] «' + h.clausula + '» — ' + (h.estado === 'con_duda' ? 'tiene una duda sin resolver: ' + (h.duda || '') : h.motivo || 'sin cita en lo raspado'))
const task =
  'Eres el escritor del manual de marca de un negocio. Más abajo tienes (1) el manual vigente en JSON, (2) la MATERIA cruda de lo que el negocio publicó de sí mismo, tal como se raspó, y (3) la lista de afirmaciones del manual que NO tienen respaldo en esa materia.\n\n' +
  'Corrige SOLO esas afirmaciones, UNA vez: o la respaldas con una cita LITERAL de la materia (y entonces la conservas), o la quitas. No agregues hechos que no estén en la materia. No cambies lo creativo (voz, personalidad, tono, ideas). ' +
  'No toques el campo `tagline`: lo escribe el sistema. Responde SOLO con un JSON: el manual completo, con las mismas claves del manual vigente.\n\n' +
  '## AFIRMACIONES SIN RESPALDO\n' + (lista.length ? lista.join('\n') : '(ninguna: solo falta el eslogan, que lo escribe el sistema)') + '\n\n' +
  '## MANUAL VIGENTE\n' + JSON.stringify(p.manual_vigente) + '\n\n' +
  '## MATERIA CRUDA (propia del negocio)\n' + String(p.materia.texto || '')
return [{ json: { ...e, autor_task: task, autor_step: 'manual-autor-s4', hallazgos_n: hallazgos.length } }]

// ② LA VUELTA DEL AUTOR (S4). Un fallo declarado del agente o un JSON que no se puede leer NO se inventa: el manual sigue como estaba y se DICE.
// Lee el JSON de forma tolerante (el primer objeto balanceado del texto). El costo es el que reporta el corredor (sin costo reportado, 0 y se declara).
const est = $('② Autor · pedido').first().json
const r = $input.first().json || {}
const c = r.body ? r.body : r
const fallo = c.success === false ? String(c.error || c.error_kind || 'sin detalle') : null
const texto = fallo ? '' : String(c.response || c.result || c.output || c.text || '')
const costo = typeof c.cost_usd === 'number' ? c.cost_usd : typeof c.costUsd === 'number' ? c.costUsd : 0
function primerObjeto(t) {
  const i = t.indexOf('{')
  if (i < 0) return null
  let d = 0, dentro = false, esc = false
  for (let k = i; k < t.length; k++) {
    const ch = t[k]
    if (dentro) { if (esc) esc = false; else if (ch === '\\') esc = true; else if (ch === '"') dentro = false; continue }
    if (ch === '"') dentro = true
    else if (ch === '{') d++
    else if (ch === '}') { d--; if (d === 0) { try { return JSON.parse(t.slice(i, k + 1)) } catch (_) { return null } } }
  }
  return null
}
const obj = texto ? primerObjeto(texto) : null
const despues = obj && typeof obj === 'object' && !Array.isArray(obj) ? (obj.manual && typeof obj.manual === 'object' ? obj.manual : obj) : null
const nota = fallo ? 'el autor FALLÓ · ' + fallo : !texto.trim() ? 'la vuelta del autor llegó vacía' : !despues ? 'la respuesta del autor no traía un JSON legible' : null
return [{ json: { ...est, despues: despues || est.prep.manual_vigente, autor_fallo: nota, costo_usd: (Number(est.costo_usd) || 0) + costo } }]

// ④ EL JUEZ DE FIDELIDAD (paso nuevo, aditivo; el del cimiento cerrado NO se toca). Misma vara que siempre: puntúa 0..1 cuán soportado está cada campo, umbral 0,85, gateados `positioning` e `icp_summary`.
// 🔴 LA EVIDENCIA ES SOLO FUENTE CRUDA (firma D1): sale de `evidencia_del_juez` de la puerta (propia + humana). NUNCA documentos de ICP, resúmenes del descubrimiento ni trozos sintéticos del cerebro.
// Cabe en 14.000 caracteres (el corredor admite 16.000): si no cabe, CEDE LA EVIDENCIA, nunca los campos, y se declara.
const est = $('② Autor · vuelta').first().json
const r1 = $input.first().json || {}
const recomprobado = r1.body ? r1.body : r1
const manual1 = recomprobado && recomprobado.manual ? recomprobado.manual : est.despues
const CAMPOS = ['positioning', 'icp_summary', 'voice_description', 'customer_angle', 'retention_notes']
const TOPE = 14000
const PROSA = 'Eres un evaluador de FIDELIDAD (groundedness). Dada la EVIDENCIA real del cliente y los CAMPOS de un manual de marca, puntúa de 0 a 1 qué tan soportado por la evidencia está cada campo (1 = totalmente respaldado · 0 = inventado o contradice). LLAMA AL TOOL `emit_fidelity_scores` con tus puntajes (un número de 0 a 1 por campo). NO narres: usa el tool.\n\n'
const campos = JSON.stringify(CAMPOS.map((f) => ({ field: f, value: String(manual1[f] || '') })))
const cabEv = 'EVIDENCIA (solo el material crudo que el negocio publicó de sí mismo):\n'
const cabCampos = '\n\nCAMPOS:\n'
let ev = String((est.prep.evidencia_del_juez && est.prep.evidencia_del_juez.texto) || '')
const cabeEntera = PROSA.length + cabEv.length + ev.length + cabCampos.length + campos.length <= TOPE
let evidencia_recortada = est.prep.evidencia_del_juez ? est.prep.evidencia_del_juez.recortada === true : false
if (!cabeEntera) { ev = ev.slice(0, Math.max(0, TOPE - (PROSA.length + cabEv.length + cabCampos.length + campos.length))); evidencia_recortada = true }
const task = PROSA + cabEv + ev + cabCampos + campos
return [{ json: { ...est, manual1, puerta1: { introducidos: recomprobado.introducidos || [], retirados: recomprobado.retirados || [], eslogan: recomprobado.eslogan || null }, juez_task: task.slice(0, TOPE), juez_step: 'manual-juez-fidelidad', evidencia_recortada, evidencia_excluida: (est.prep.evidencia_del_juez && est.prep.evidencia_del_juez.excluidas) || [] } }]

// ④ EL VEREDICTO DEL JUEZ. Lee los puntajes que el corredor captura del tool (`fidelity_scores.scores`); si no vinieron, NO se inventan: queda `puntajes: null` y se declara.
// El veredicto NO bloquea ni dispara otro ciclo: se muestra en la tarjeta (los gateados bajo el umbral se marcan) y la persona decide. El lazo A del cimiento no se toca ni se llama.
const est = $('④ Juez · pedido').first().json
const r = $input.first().json || {}
const c = r.body ? r.body : r
const UMBRAL = 0.85
const GATEADOS = ['positioning', 'icp_summary']
const costo = typeof c.cost_usd === 'number' ? c.cost_usd : 0
const s = c.fidelity_scores && c.fidelity_scores.scores && typeof c.fidelity_scores.scores === 'object' ? c.fidelity_scores.scores : null
const puntajes = s ? Object.fromEntries(Object.keys(s).map((k) => [k, typeof s[k] === 'number' ? s[k] : null])) : null
const bajo = puntajes ? GATEADOS.filter((f) => typeof puntajes[f] !== 'number' || puntajes[f] < UMBRAL) : GATEADOS
const fidelidad = { umbral: UMBRAL, puntajes, bajo_umbral: bajo, sin_veredicto: !puntajes, evidencia_recortada: est.evidencia_recortada === true }
return [{ json: { ...est, fidelidad, costo_usd: (Number(est.costo_usd) || 0) + costo } }]

// ⑤ LA OPINIÓN DE GPT CIEGO (S6). Arma el cuerpo de `POST /api/manual/opinion`: el manual (ya cerrado por la puerta) y nada más. GPT NO ve hallazgos, puntajes, versiones anteriores ni lo que corrigió el autor:
// la ruta arma el pedido con el manual en limpio y la materia cruda, con la UNA pregunta general.
const est = $('④ Juez · veredicto').first().json
const body = { client_id: est.client_id, dry_run: false, workflow_id: est.workflow_id, workflow_execution_id: est.workflow_execution_id, manual: est.manual1 }
return [{ json: { ...est, opinion_body: body } }]

// ⑤ LA VUELTA DE GPT. Su texto es una OPINIÓN (se rotula como tal): nunca es dato confirmado ni cuenta como desacuerdo.
// Si GPT falló (tras los 3 reintentos de la ruta) NO bloquea: la tarjeta sale «SIN SEGUNDA MIRADA».
const est = $('⑤ Opinión · pedido').first().json
const r = $input.first().json || {}
const c = r.body ? r.body : r
const ok = c.ok === true && typeof c.opinion === 'string' && c.opinion.trim() !== ''
const opinion = ok ? { ok: true, texto: c.opinion } : { ok: false, error: String(c.error || c.detalle || 'el revisor externo no respondió') }
const costo = typeof c.costo_usd === 'number' ? c.costo_usd : 0
return [{ json: { ...est, opinion, hay_opinion: ok, costo_usd: (Number(est.costo_usd) || 0) + costo } }]

// ⑥ LA VUELTA DEL AUTOR a la opinión. Lector tolerante; un fallo o un JSON ilegible NO se inventa: el manual sigue como estaba (ya cerrado por la puerta) y la respuesta queda vacía, declarado.
const est = $('⑥ Respuesta · pedido').first().json
const r = $input.first().json || {}
const c = r.body ? r.body : r
const fallo = c.success === false ? String(c.error || c.error_kind || 'sin detalle') : null
const texto = fallo ? '' : String(c.response || c.result || c.output || c.text || '')
const costo = typeof c.cost_usd === 'number' ? c.cost_usd : 0
function primerObjeto(t) {
  const i = t.indexOf('{')
  if (i < 0) return null
  let d = 0, dentro = false, esc = false
  for (let k = i; k < t.length; k++) {
    const ch = t[k]
    if (dentro) { if (esc) esc = false; else if (ch === '\\') esc = true; else if (ch === '"') dentro = false; continue }
    if (ch === '"') dentro = true
    else if (ch === '{') d++
    else if (ch === '}') { d--; if (d === 0) { try { return JSON.parse(t.slice(i, k + 1)) } catch (_) { return null } } }
  }
  return null
}
const obj = texto ? primerObjeto(texto) : null
const manual2 = obj && obj.manual && typeof obj.manual === 'object' && !Array.isArray(obj.manual) ? obj.manual : null
const respuesta = obj && Array.isArray(obj.respuesta) ? obj.respuesta.filter((x) => x && typeof x.punto === 'string' && (x.decision === 'tomada' || x.decision === 'no_tomada') && typeof x.razon === 'string') : []
const nota = fallo ? 'el autor FALLÓ al responder · ' + fallo : !manual2 ? 'la respuesta del autor no traía un manual legible' : null
return [{ json: { ...est, despues2: manual2 || est.manual1, respuesta_del_autor: respuesta, respuesta_fallo: nota, costo_usd: (Number(est.costo_usd) || 0) + costo } }]

// ⑥ El manual final es el que salió de la puerta DESPUÉS de la respuesta del autor.
const est = $('⑥ Respuesta · vuelta').first().json
const r = $input.first().json || {}
const c = r.body ? r.body : r
return [{ json: { ...est, manual_final: c && c.manual ? c.manual : est.despues2, manual_final_origen: 'respuesta', puerta2: { introducidos: (c && c.introducidos) || [], retirados: (c && c.retirados) || [] } } }]

// ⑤ GPT no opinó (falló tras los 3 reintentos): NO bloquea. El manual final es el que ya cerró la puerta, y la tarjeta saldrá «SIN SEGUNDA MIRADA».
const est = $input.first().json
return [{ json: { ...est, manual_final: est.manual1, manual_final_origen: 'sin_opinion' } }]

// ⑦ EL BORRADOR Y LA TARJETA (S8). Arma el cuerpo de `POST /api/manual/borrador` con el manual FINAL (el que salió de la última puerta). `dry_run` es false aquí porque este nodo solo se alcanza con dry_run=false.
// Lo retirado sin fuente lo recalcula la ruta y queda solo en el registro interno del borrador: este flujo NO lo manda a ninguna bandeja ni canal.
const est = $input.first().json
const con = est.manual_final_origen === 'respuesta'
const body = {
  client_id: est.client_id, dry_run: false, workflow_id: est.workflow_id, workflow_execution_id: est.workflow_execution_id,
  manual: est.manual_final, opinion: est.opinion || null, respuesta_del_autor: con ? est.respuesta_del_autor : null,
  costo_usd: Math.round((Number(est.costo_usd) || 0) * 1e6) / 1e6, fidelidad: est.fidelidad || null,
  // ADENDA 7 (30-oct): la jefatura NO valida el manual: tarjeta en la bandeja del dueño como siempre; el tipo de negocio y dónde se buscó fijan lo obligatorio
  validador: 'bandeja', tipo_de_negocio: est.tipo_de_negocio || null, buscado_en: est.buscado_en || null,
}
return [{ json: { ...est, borrador_body: body } }]

// ⑧ CIERRE con borrador: dice qué quedó escrito (borrador + tarjeta) y cuánto costó. Un error de la ruta se DICE (no se esconde). Nada de lo retirado sin fuente sale de este flujo hacia ningún canal.
const est = $('⑦ Borrador · pedido').first().json
const r0 = $input.first().json || {}
const r = r0.body ? r0.body : r0
return [{ json: { fin: r.ok === false ? 'borrador_con_error' : r.sin_cambios ? 'sin_cambios' : 'borrador_escrito', output_id: r.output_id || null, hitl_id: r.hitl_id || null, version_nueva: r.version_nueva === undefined ? null : r.version_nueva, costo_usd: est.costo_usd, error: r.error || null, validado_por_la_jefatura: !!(r.jefatura && r.jefatura.valida), motivos_de_la_jefatura: (r.jefatura && r.jefatura.motivos) || null, autor_fallo: est.autor_fallo || null, respuesta_fallo: est.respuesta_fallo || null } }]

// ⑧ CIERRE sin pasos de modelo: la preparación falló, no había hallazgos, o era dry_run. Dice qué pasó. Costo 0. Nada de lo retirado sin fuente sale de este flujo hacia ningún canal.
const e = $input.first().json || {}
return [{ json: { fin: 'sin_modelo', motivo: e.motivo || '', dry_run: e.dry_run === true, costo_usd: 0 } }]
